def run_jobs(jobs: list[dict], executor) -> list[dict]:
    """Run scheduled jobs sequentially using the legacy error-handling rules."""
    run_log: list[dict] = []

    for job in jobs:
        name = job["name"]
        policy = job["on_error"]["policy"]
        retries = job["on_error"]["retries"]

        attempts = 0
        succeeded = False

        max_attempts = retries + 1 if policy == "RETRY" else 1

        for _ in range(max_attempts):
            attempts += 1
            try:
                executor(job)
            except Exception:
                continue
            else:
                succeeded = True
                break

        if succeeded:
            run_log.append(
                {
                    "name": name,
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )
            continue

        if policy == "CONTINUE":
            run_log.append(
                {
                    "name": name,
                    "attempts": attempts,
                    "outcome": "skip",
                    "audits": ["BATCH_ROWSKIP"],
                }
            )
            continue

        run_log.append(
            {
                "name": name,
                "attempts": attempts,
                "outcome": "abort",
                "audits": [],
            }
        )
        break

    return run_log
